class BankAccount {
    String holder;
    double balance;

    void deposit(double amt) {
        balance = balance + amt;
    }

    void printStatement() {
        System.out.println(holder + ": $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount acc1 = new BankAccount();
        acc1.holder = "Alice";
        acc1.balance = 500.0;
        acc1.deposit(200.0);

        BankAccount acc2 = new BankAccount();
        acc2.holder = "Bob";
        acc2.balance = 1000.0;
        acc2.deposit(50.0);

        acc1.printStatement();
        acc2.printStatement();
    }
}

