class InventoryItem {
    String name;
    int stock;

    void restock(int qty) {
        stock = stock + qty;
    }

    void showInventory() {
        System.out.println(name + ": " + stock + " units in stock");
    }
}

public class Main {
    public static void main(String[] args) {
        InventoryItem i1 = new InventoryItem();
        i1.name = "USB-C Cable";
        i1.stock = 20;
        i1.restock(30);

        InventoryItem i2 = new InventoryItem();
        i2.name = "HDMI Adapter";
        i2.stock = 10;
        i2.restock(5);

        i1.showInventory();
        i2.showInventory();
    }
}

